import json,numpy as np
from collections import defaultdict
rows=[]
for f in ['sweep1','sweep2','sweep3','sweep4']: rows+=json.load(open(f'/app/{f}.json'))
pp=[r for r in rows if r['config']['method']=='ppo']
g=defaultdict(list)
for r in pp: g[(r['kl'],r['config']['len_pen'])].append((r['mean_len'],r['proxy_reward']))
keys=sorted(g); Lm=np.array([np.mean([a for a,b in g[k]]) for k in keys]); Pm=np.array([np.mean([b for a,b in g[k]]) for k in keys]); W=np.array([len(g[k]) for k in keys])
kls=sorted(set(k[0] for k in keys)); G=np.array([kls.index(k[0]) for k in keys])
def fit(l0,sl):
    X=np.zeros((len(keys),len(kls)+1)); X[np.arange(len(keys)),G]=1; X[:,-1]=np.tanh((Lm-l0)/sl)
    sw=np.sqrt(W); coef=np.linalg.lstsq(X*sw[:,None],Pm*sw,rcond=None)[0]; return np.sum(W*(X@coef-Pm)**2),coef,X@coef
for l0 in [278,282.5,287,292]:
    best=min((fit(l0,sl)[0],sl) for sl in np.arange(70,150,0.5)); rr,coef,pred=fit(l0,best[1])
    print('l0',l0,'sl',best[1],'rss',round(rr,5),'coef',np.round(coef,4))
    if l0==282.5:
        for k,p,pr,w in zip(keys,Pm,pred,W): print('  ',k,w,round(p-pr,4))
